'use client';

// Toasts ("Checked in · Ebb", "Done. Added to your proof log.").
// Generated by the shadcn/ui CLI and adapted: it follows Tide's own theme
// (light or dark) instead of next-themes, uses neutral icons only (no red
// error style), sits above the tab bar so it never covers navigation, and in
// v2 is a rounded pill with a solid ledge like the rest of the app.
import { Toaster as Sonner, type ToasterProps } from 'sonner';
import { CircleCheckIcon, InfoIcon } from 'lucide-react';
import { useThemeScheme } from '@/lib/theme/useThemeScheme';

const Toaster = ({ ...props }: ToasterProps) => {
  const scheme = useThemeScheme();

  return (
    <Sonner
      theme={scheme}
      position="bottom-center"
      offset={{ bottom: 168 }}
      mobileOffset={{ bottom: 168 }}
      className="toaster group"
      icons={{
        success: <CircleCheckIcon className="size-5" aria-hidden />,
        info: <InfoIcon className="size-5" aria-hidden />,
        warning: <InfoIcon className="size-5" aria-hidden />,
        error: <InfoIcon className="size-5" aria-hidden />,
      }}
      style={
        {
          '--normal-bg': 'var(--surface)',
          '--normal-text': 'var(--ink)',
          '--normal-border': 'var(--line)',
          '--border-radius': '20px',
        } as React.CSSProperties
      }
      toastOptions={{
        classNames: {
          toast: 'cn-toast !border-2 font-display text-body font-bold !shadow-[0_4px_0_var(--line)]',
        },
      }}
      {...props}
    />
  );
};

export { Toaster };
